{"command":"cd /testbed && python3 - <<'EOF'
import sqlite3, json
con = sqlite3.connect("file:/var/lib/acme/crm.sqlite?mode=ro", uri=True)
con.row_factory = sqlite3.Row
tables = ["customers", "orders", "customer_history", "audit_events"]
snap = json.load(open("/tmp/pre_delete_snapshot.json"))
ok = True
for t in tables:
    now = {r["orders" and "order_id" if False else list(r.keys())[0]]: None for r in []}  # noop
    rows = [dict(r) for r in con.execute(f"SELECT * FROM {t}")]
    pk = {"customers":"customer_id","orders":"order_id","customer_history":"history_id","audit_events":"event_id"}[t]
    before = {r[pk]: r for r in snap[t]}
    after  = {r[pk]: r for r in rows}
    added = sorted(set(after) - set(before))
    removed = sorted(set(before) - set(after))
    changed = []
    for k in sorted(set(before) & set(after)):
        if before[k] != after[k]:
            changed.append((k, before[k], after[k]))
    print(f"--- {t}: before={len(before)} after={len(after)} added={len(added)} removed={len(removed)} changed={len(changed)}")
    for a in added:
        print("  ADDED:", after[a])
    for rm in removed:
        print("  REMOVED:", before[rm]); ok = False
    for k, b, a in changed:
        diff = {f: (b[f], a[f]) for f in b if b[f] != a[f]}
        print(f"  CHANGED {k}: {diff}")
        if k in before and b.get("status") not in (None, "active"):
            pass
        # any change to a non-target row is a violation
print()
print("=== AUDIT EVENTS ===")
for r in con.execute("SELECT * FROM audit_events"):
    print(dict(r))
# integrity: foreign keys
fk = con.execute("PRAGMA foreign_key_check").fetchall()
print("foreign_key_check:", fk if fk else "OK")
EOF"}

